import os
for root,ds,fs in os.walk('studies'):
 for f in fs: print(os.path.join(root,f))

from pypdf import PdfReader
import re,gzip,glob
for i in range(1,6):
 text='\n'.join(p.extract_text() or '' for p in PdfReader(f'studies/papers/paper_{i}.pdf').pages)
 print('\n===== PAPER',i,'=====')
 for m in re.finditer(r'depriv|charcoal|phenol|stripp|culture conditions|cell culture',text,re.I):
  print(text[max(0,m.start()-300):m.end()+650].replace('\n',' '))
 print('\n=== GEO protocols ===')
 f=glob.glob(f'studies/data/raw/paper_{i}_*series*')[0]
 for line in gzip.open(f,'rt'):
  if any(x in line for x in ['!Sample_growth_protocol','!Sample_treatment_protocol']): print(line[:18000])

